const taskData={run:{title:'Prepare an observation',verbs:'Retrieve · structure · prepare',source:'Supplied material, journey context and field meaning',output:'A source-linked draft with unresolved information',human:'A colleague checks source fidelity, subject and gaps.',scope:'No customer assessment, approval or authoritative record change.'},develop:{title:'Develop a FenX behaviour',verbs:'Analyse · draft · challenge',source:'Instruction, intended behaviour and system context',output:'A requirement and adverse test for review',human:'Domain and engineering review establish intent and acceptance.',scope:'The resulting feature may be deterministic; it need not run an AI model.'},change:{title:'Analyse an instruction change',verbs:'Compare · trace · challenge',source:'Source revision, interpretation and dependent objects',output:'Candidates for impact review',human:'Responsible reviewers determine applicability and controlled change.',scope:'No object updates automatically. Prior evidence retains its scope.'}};
function selectTask(id){document.body.dataset.task=id;document.querySelectorAll('[data-task]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.task===id)));document.querySelectorAll('[data-group]').forEach(g=>g.classList.toggle('dim',g.dataset.group!==id));for(const [key,value] of Object.entries(taskData[id]))document.querySelectorAll(`[data-task-field="${key}"]`).forEach(n=>n.textContent=value);document.querySelectorAll('[data-task-specimen]').forEach(n=>n.hidden=n.dataset.taskSpecimen!==id);}
document.querySelectorAll('[data-task]').forEach(b=>b.addEventListener('click',()=>selectTask(b.dataset.task)));
document.querySelectorAll('[data-revision-toggle]').forEach(n=>n.addEventListener('change',()=>{document.body.classList.toggle('revision-off',!n.checked);document.body.classList.toggle('revision-on',n.checked);document.querySelectorAll('[data-revision-status]').forEach(el=>el.textContent=n.checked?'Proposed revision selected · impact review only':'Baseline selected · no revision in scope');}));
document.querySelectorAll('[data-interface-toggle]').forEach(n=>n.addEventListener('change',()=>{document.body.classList.toggle('interface-on',n.checked);document.querySelectorAll('[data-interface-message]').forEach(el=>el.textContent=n.checked?'Interface assumed. Actual identity, permission, quality and operation remain separate.':'No interface assumed. Supplied-document work can still proceed.');document.querySelectorAll('[data-live-path]').forEach(el=>el.style.opacity=n.checked?'1':'.2');}));
document.querySelectorAll('[data-meaning]').forEach(n=>n.addEventListener('click',()=>{let id=n.dataset.meaning;document.body.dataset.meaning=id;document.querySelectorAll('[data-meaning]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.meaning===id)));document.querySelectorAll('[data-meaning-part]').forEach(el=>el.classList.toggle('dim',el.dataset.meaningPart!==id));document.querySelectorAll('[data-meaning-detail]').forEach(el=>el.hidden=el.dataset.meaningDetail!==id);}));
document.querySelectorAll('[data-inspect]').forEach(b=>b.addEventListener('click',()=>{let d=document.querySelector('dialog');d.querySelector('h2').textContent=b.dataset.inspect;d.showModal();}));document.querySelector('dialog [data-close]')?.addEventListener('click',()=>document.querySelector('dialog').close());
document.querySelectorAll('[data-include]').forEach(n=>n.addEventListener('change',()=>{document.querySelectorAll(`[data-inclusion="${n.dataset.include}"]`).forEach(el=>el.classList.toggle('dim',!n.checked));document.querySelector('[data-packet-status]')?.replaceChildren(document.createTextNode([...document.querySelectorAll('[data-include]')].every(e=>e.checked)?'Context selected; applicability, ownership and consumption still need review.':'The packet is incomplete. Missing context stays visible.'));}));
if(document.querySelector('[data-task]'))selectTask(document.body.dataset.task||'develop');
